   957→      console.log('[ai] Transcribing audio with Whisper (5s cap)...');
   958→      whisperResult = await Promise.race([
   959→        transcribeAudioWithWhisper(audioData, options),
   960→        new Promise((resolve) => setTimeout(() => {
   961→          console.warn('[ai] Whisper 5s cap hit — using browser transcription');
   962→          resolve(null);
