   964→      ]);
   965→      if (whisperResult && whisperResult.text && whisperResult.text.trim().length > 20) {
   966→        finalTranscription = whisperResult.text;
   967→        console.log(`[ai] Whisper transcription: ${finalTranscription.length} chars (replaced browser transcription)`);
