   973→    }
   974→  }
   975→
   976→  // Step 2: Run all analyses in parallel with PER-PROMISE timeouts
   977→  // BUG FIX (Feb 15, 2026): The old global timeout (Promise.race with 25s) was DESTRUCTIVE —
   978→  // when it fired, it replaced ALL results with rejections, including promises that had already
   979→  // completed successfully. E.g., vision analysis would succeed at 10s but get discarded at 25s
   980→  // because voice analysis was still running. Fix: wrap each promise individually with its own
   981→  // timeout, then use Promise.allSettled which preserves all settled results.
   982→  const PER_PROMISE_TIMEOUT_MS = 22000;
   983→
   984→  function withTimeout(promise, ms, label) {
   985→    return new Promise((resolve, reject) => {
   986→      const timer = setTimeout(() => {
   987→        console.warn(`[video-analysis] ${label} timed out after ${ms}ms`);
   988→        reject(new Error(`${label} timeout after ${ms}ms`));
   989→      }, ms);
   990→      promise.then(
   991→        val => { clearTimeout(timer); resolve(val); },
   992→        err => { clearTimeout(timer); reject(err); }
   993→      );
   994→    });
   995→  }
   996→
   997→  // FIX (Feb 15, 2026): Pass transcription context to video presentation analysis
   998→  // so the text-based LLM can generate personalized coaching from speech patterns
   999→  const presentationOptions = {
  1000→    ...options,
  1001→    transcription: finalTranscription,
  1002→    durationSeconds,
  1003→    question,
  1004→  };
  1005→
  1006→  const analysisPromises = [
  1007→    withTimeout(analyzeInterviewResponse(question, finalTranscription, keyPoints, options), PER_PROMISE_TIMEOUT_MS, 'contentAnalysis'),
  1008→    withTimeout(generateInterviewCoaching(question, finalTranscription, { score: 5, strengths: [], improvements: [] }, options), PER_PROMISE_TIMEOUT_MS, 'contentCoaching'),
  1009→    withTimeout(analyzeVideoPresentation(frames, presentationOptions), PER_PROMISE_TIMEOUT_MS, 'videoPresentation')
  1010→  ];
  1011→
  1012→  // Add voice quality analysis if we have audio
  1013→  if (audioData) {
  1014→    analysisPromises.push(withTimeout(analyzeVoiceQuality(finalTranscription, durationSeconds, options), PER_PROMISE_TIMEOUT_MS, 'voiceAnalysis'));
  1015→  }
  1016→
  1017→  // Promise.allSettled waits for ALL promises to settle — each has its own timeout so
  1018→  // successful results are never discarded by a slow sibling promise
  1019→  let settled;
  1020→  try {
  1021→    settled = await Promise.allSettled(analysisPromises);
  1022→  } catch (err) {
  1023→    console.error('[video-analysis] Promise.allSettled unexpected error:', err.message);
  1024→    settled = analysisPromises.map(() => ({ status: 'rejected', reason: err }));
  1025→  }
  1026→
  1027→  // Extract results with fallbacks for any failed analyses
  1028→  // BUG FIX: Use helper function with multiple safety layers to prevent null crashes.
  1029→  // Previous null checks still let through edge cases where AI returned non-null truthy values
  1030→  // that were missing expected fields, causing TypeError: Cannot read properties of null.
  1031→  function safeExtract(index, fallback) {
  1032→    try {
  1033→      const s = settled[index];
  1034→      if (s && s.status === 'fulfilled' && s.value != null && typeof s.value === 'object') {
  1035→        return s.value;
  1036→      }
  1037→    } catch (e) {
  1038→      console.error(`[video-analysis] safeExtract(${index}) error:`, e.message);
  1039→    }
  1040→    return fallback;
  1041→  }
  1042→
  1043→  const contentAnalysis = safeExtract(0, {
  1044→    score: 0, _failed: true, strengths: [], improvements: ['Content analysis failed — please try again'],
  1045→    covered_points: [], missed_points: [], detailed_feedback: 'AI content analysis could not be completed. Please record another answer to get detailed feedback on your response.'
  1046→  });
  1047→  const contentCoaching = safeExtract(1, {
