  1059→
  1060→  // Log any failures for debugging
  1061→  settled.forEach((s, i) => {
  1062→    if (s.status === 'rejected') {
  1063→      const names = ['contentAnalysis', 'contentCoaching', 'videoAnalysis', 'voiceAnalysis'];
  1064→      console.error(`[video-analysis] ${names[i]} failed:`, s.reason?.message || s.reason);
  1065→    }
  1066→  });
  1067→
  1068→  // Algorithmic speech analysis (always works — no AI calls)
  1069→  const speechAnalysis = analyzeSpeechPatterns(finalTranscription, durationSeconds);
  1070→
  1071→  // BUG FIX: Wrap result assembly in try/catch — if ANY field access crashes, return a safe default
  1072→  try {
  1073→    // Calculate category scores — use 0 for failed analysis (don't inflate with default 5)
  1074→    const contentScore = contentAnalysis.score || 0;
  1075→    const contentFailed = contentAnalysis._failed === true;
  1076→    let communicationScore = speechAnalysis.communication_score || 5;
