  1086→
  1087→    // Weighted overall score — if content failed, only use communication + presentation
  1088→    let overallScore;
  1089→    if (contentFailed) {
  1090→      // Content analysis failed — compute from available scores only, don't let 0 drag down
  1091→      overallScore = Math.round(
  1092→        (communicationScore * 0.45 + presentationScore * 0.55) * 10
  1093→      ) / 10;
  1094→    } else {
