  1096→        (contentScore * 0.45 + communicationScore * 0.25 + presentationScore * 0.30) * 10
  1097→      ) / 10;
  1098→    }
  1099→
  1100→    return {
  1101→      overall_score: overallScore,
  1102→      _content_failed: contentFailed,
  1103→
  1104→      // Category breakdowns — use optional chaining (?) as final safety net
  1105→      content: {
