  1221→// AI interviewer conducts a conversational interview turn
  1222→async function conductInterviewTurn(conversation, baseQuestions, currentQuestionIndex, targetRole, options = {}) {
  1223→  // Send last 12 turns for better context on follow-ups
  1224→  const recentConvo = conversation.slice(-12);
  1225→  const convoText = recentConvo.map(turn => {
  1226→    if (turn.role === 'interviewer') return `INTERVIEWER: ${turn.text}`;
  1227→    return `CANDIDATE: ${turn.text}`;
  1228→  }).join('\n\n');
  1229→
  1230→  const candidateTurnCount = conversation.filter(t => t.role === 'candidate').length;
  1231→  const followUpCount = conversation.filter(t => t.role === 'interviewer' && (t.action === 'follow_up' || t.action === 'challenge')).length;
  1232→  const remainingQuestions = baseQuestions.slice(currentQuestionIndex);
  1233→  const nextPlannedQuestion = remainingQuestions.length > 0
  1234→    ? remainingQuestions[0].question_text
  1235→    : null;
  1236→
