   735→      err.allProvidersFailed = true;
   736→      err.triedProviders = [];
   737→      err.totalElapsedMs = Date.now() - callStart;
   738→      aiCallLogger.logCall({
   739→        module: callMeta.module || 'unknown',
   740→        feature: callMeta.feature || '',
   741→        modality,
   742→        provider: 'none',
   743→        model: '',
   744→        latencyMs: Date.now() - callStart,
   745→        success: false,
   746→        errorMessage: err.message,
   747→        fallbackChain: allChain,
   748→        userId: callMeta.userId || null,
   749→      });
