   751→    }
   752→
   753→    // Per-provider timeout: 8s for TTS/ASR, 15s for LLM, 30s for vision (multi-image), 10s default
   754→    const perProviderTimeoutMs = modality === 'tts' || modality === 'asr' ? 8000
   755→      : modality === 'llm' ? 15000
   756→      : modality === 'vision' ? 30000
   757→      : 10000;
   758→
   759→    // Total cascade timeout — absolute wall-clock cap for entire fallback chain
   760→    const totalTimeoutMs = TOTAL_CASCADE_TIMEOUT[modality] || 30000;
   761→
   762→    // Number of providers to race in parallel
   763→    const raceCount = PARALLEL_RACE_COUNT[modality] || 1;
   764→
   765→    let lastError;
   766→    let failedProvider = null;
   767→
   768→    // ── Phase 1: Parallel Race (top N providers simultaneously) ──────
   769→    // Dramatically reduces latency when primary provider is slow/down.
   770→    // First success wins; if ALL raced providers fail, fall through to sequential.
   771→    if (raceCount > 1 && chain.length >= 2) {
   772→      const raceProviders = chain.slice(0, Math.min(raceCount, chain.length));
   773→
   774→      try {
   775→        const raceResult = await this._raceProviders(
   776→          raceProviders, executeFn, perProviderTimeoutMs, modality, callMeta, callStart, triedProviders
   777→        );
