   796→      if (elapsed >= totalTimeoutMs) {
   797→        console.warn(`[ai-provider] ⏱️ Total cascade timeout (${totalTimeoutMs}ms) hit after ${elapsed}ms — tried: ${triedProviders.join(' → ')}`);
