          'selfhosted_stt',      // Layer 2: whisper.cpp tiny.en (CPU, no API key)
          'groq_whisper',        // Layer 3: Groq whisper-large-v3-turbo (FREE!)
          'deepgram_stt',        // Layer 4: Deepgram Nova-2 (paid)
        ],
      },

